#define EPSILON 0.0005
#define MIN_DISTANCE 0.005
#define MAX_DISTANCE 75. 
#define PRECISION 0.001
#define MAX_STEPS 110
#define BALL_RADIUS 3.2
#define SHAPE_CYCLE 10. // how often (seconds) a 'gyroid' variant should morft
#define MORFING_SPEED 3. // how much time (second) morfing should take
#define REPEAT_PATTERN 0.0
#define REPEAT_PATTERN_X 0.0
#define REPEAT_PATTERN_Y 0.0
#define DAMPING_TIME 4.2 // how much time (seconds) a single wave will exist (thus propage)
#define WAVE_SIZE 0.3
#define WAVES_CYCLE 7.4 // full cycle of X waves
#define WAVES_DISTANCE 0.5 // time distance between subsequent waves (in  a loop)
#define WAVES_COUNT 8
#define DISTANCE_METHODS 8. // how many methods of measuring methods we do have


#define TIME_SPEED_FACTOR 1.1
#define PI 3.1415926
#define WAVE_CENTER_WANDERING_SPEED -(TIME_SPEED_FACTOR / 4.) // speed of chaning initial position of subsequent waves

struct Material {
    vec3 ambientColor;
    vec3 diffuseColor;
    vec3 specularColor;
    float alpha;
};



Material greyM() {
  vec3 aCol = vec3(0.7);
  vec3 dCol = vec3(0.7);
  vec3 sCol = vec3(0.7);
  float a = 55.;

  return Material(aCol, dCol, sCol, a);
}



Material grey;


// an array with various 'shapes' of a gyroid
const float ppTable[5] = float[5](
    8.0, 6.0, 3.0, 5., 10.
);


float sdSphere(vec3 p, vec3 c, float r) {
    //vec3 p = pr * tm;
    float shapesCount = float(ppTable.length());
    int shape2 = int(mod(mod(iTime / SHAPE_CYCLE, shapesCount * SHAPE_CYCLE), shapesCount));
    int shape1 = int(mod((float(shape2 + 1)), shapesCount));
    vec3 np = vec3(p);
    //np.z = sin(np.z * 3.) * 1.2;
//    np.x = sin(np.z * 4.) * 1.1;
//    np.y = sin(np.y * 4.) * 1.1;
 //   np.y = sin(np.x * 4.) * 1.1;
 //   np.y = cos(sin(np.x * 4.) * 1.1) * 1.4;
    float distSphere = abs(length(np - c) - r) - 0.3; // abs and (-0.3) at the end is to make a shell instead of a sphere 
    float gyroidDistance;
   // shape1 = 4;
    float cycleTime = mod(iTime, SHAPE_CYCLE);
    vec3 pp1 = ppTable[shape1] * p; vec3 ve1 = pp1.xzz;
    vec3 pp2 = ppTable[shape2] * p; vec3 ve2 = pp1.yxz;


    if (cycleTime < MORFING_SPEED) {
         ve1 = mix(pp2.xzz, ve1, cycleTime / MORFING_SPEED);   
         ve2 = mix(pp2.yxz, ve2, cycleTime / MORFING_SPEED);   
    }


   gyroidDistance = abs(dot(sin(ve1), cos(ve2)) / 10.1) - 0.09;

   return max(distSphere, gyroidDistance);
   //return distSphere;
}

vec3 applyMovement(vec3 p) {
    return p * rotateReverseY(iTime * TIME_SPEED_FACTOR / 4.);
}

vec3 applyOppositeMovement(vec3 p) {
    return p * rotateY(iTime * TIME_SPEED_FACTOR / 4.);
}


float scene(vec3 p) {
    float zi = REPEAT_PATTERN > 0. ? mod(p.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN : p.z;
    float xi = REPEAT_PATTERN_X > 0. ?  mod(p.x + 0.5 * REPEAT_PATTERN_X, REPEAT_PATTERN_X) - 0.5 * REPEAT_PATTERN_X : p.x;
    float yi = REPEAT_PATTERN_Y > 0. ?  mod(p.y + 0.5 * REPEAT_PATTERN_Y, REPEAT_PATTERN_Y) - 0.5 * REPEAT_PATTERN_Y : p.y;

    vec3 pr = vec3(xi , yi, zi);
    return sdSphere(applyMovement(p), vec3(0., 0., 0.), BALL_RADIUS); 
}



// vector normal to sphere with cener c and radius r
vec3 calcNormal(vec3 p) {
  vec2 e = vec2(1.02, -1.02) * EPSILON;
  return normalize(
    e.xyy * scene(p + e.xyy) +
    e.yyx * scene(p + e.yyx) +
    e.yxy * scene(p + e.yxy) +
    e.xxx * scene(p + e.xxx));
}


struct RaymarchRes {
    vec3 p; // surface hit point
    float d; // distance
};


RaymarchRes raymarch(vec3 ro, vec3 rd) {
    float t = MIN_DISTANCE; 
    RaymarchRes res;
    res.d = MAX_DISTANCE;

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + t * rd;
        float sf = scene(p); 
        t += sf;

        if (sf < PRECISION) { // we hit the surface at point p
            res.p = p;
            res.d = sf;
            break;
        } else if (sf > MAX_DISTANCE) break; // we did not hit anything but are to far away from camera 
            //t += sf.d; // we did not hit anything, keep on trying
    }

    res.d = t;
    return res;
}

mat3 camera(vec3 cameraPos, vec3 lookAtPoint) {
    vec3 cd = normalize(lookAtPoint - cameraPos);
    vec3 cr = normalize(cross(vec3(0, 1, 0), cd));
    vec3 cu = normalize(cross(cd, cr));

    return mat3(-cr, cu, -cd);
}

vec3 calculateCameraPosition(vec3 lookAt, vec2 uv) {
   vec3 ro = vec3(0., 4.*sin(iTime), lookAt.z - 8.); 
   //vec3 ro = vec3(2.1 + someShapingFunction(), 0. + someShapingFunction() * 1., lookAt.z - 4. + sin(iTime) * 3.); 
   return ro;
}

vec3 calculateLightPosition(vec3 lookAt) {
    vec3 lightVector = vec3(4., 2., -18.);
    return lightVector;
}

vec3 wanderOnSphere(float time, float radius, float cycle) {
    //float azimuth = sin(time) * PI / 2.;//mod(time * SPOT_LIGHT_SPEED, 1.0 * PI) + 2. * PI; 
    float azimuth = mod(time * WAVE_CENTER_WANDERING_SPEED, 2.0 * PI) + PI * 1.5 + 0.9; 
    float elevation = sin(time * PI * 0.5 + cycle) / 4.;//sin(time * SPOT_LIGHT_SPEED * 0.5) * PI * 0.5;// - 0.5; 

    // change coordinates to cartesian system
    float x = radius * cos(elevation) * cos(azimuth);
    float y = radius * sin(elevation);
    float z = radius * cos(elevation) * sin(azimuth);// + iTime * TIME_SPEED_FACTOR ;

    return vec3(x, y, z);
}

const mat3 invCovariance = mat3(
    vec3(10.0, 00.0, 0.0), 
    vec3(0.0, 1.0, 0.2),
    vec3(10.0, 3., 10.0)
);

// Mahalanobis distance
float mahalanobisDistance(vec3 pointA, vec3 pointB) {
    vec3 diff = pointA - pointB; 
    vec3 transformedDiff = invCovariance * diff; 
    return sqrt(dot(transformedDiff, diff));
}

float geodesicDistanceWithDeviation(vec3 pointA, vec3 pointB, vec3 deviationVector, float deviationScale) {
    vec3 normA = normalize(pointA);
    vec3 normB = normalize(pointB);

    float geodesicDist = acos(clamp(dot(normA, normB), -1.0, 1.0));
    float deviation = deviationScale * dot(normalize(deviationVector), normB);
    return max(0.0, geodesicDist + deviation);
}


vec3 calculateLight(vec2 fragCoord, RaymarchRes rr, vec3 rd, vec3 lo, vec3 backgroundColor) {
    vec3 po = rr.p;

    //vec3 p = po;
    float zii = REPEAT_PATTERN > 0. ? mod(po.z + 0.5 * REPEAT_PATTERN, REPEAT_PATTERN) - 0.5 * REPEAT_PATTERN : po.z;
    float xii = REPEAT_PATTERN_X > 0. ?  mod(po.x + 0.5 * REPEAT_PATTERN_X, REPEAT_PATTERN_X) - 0.5 * REPEAT_PATTERN_X : po.x;
    float yii = REPEAT_PATTERN_Y > 0. ?  mod(po.y + 0.5 * REPEAT_PATTERN_Y, REPEAT_PATTERN_Y) - 0.5 * REPEAT_PATTERN_Y : po.y;

    vec3 normalToSurfaceVector = calcNormal(po);
    vec3 l = -normalize(-lo + po); // light direction
    Material m = grey;

    vec3 pii = vec3(xii, yii, zii);
    vec3 color = m.ambientColor; 


    float light = clamp(dot(normalToSurfaceVector, l), 0., 5.);
    color *= vec3(light);
    vec3 spotLight1 = vec3(1., 0., 0.);
    int distanceMethod = int(mod(mod(iTime / WAVES_CYCLE, DISTANCE_METHODS * WAVES_CYCLE), DISTANCE_METHODS));

    for (int i = 0; i <  WAVES_COUNT; i++) {
        float dTime = float(i) * WAVES_DISTANCE;
        float cTime = iTime - dTime;
        float nCycle = floor(iTime / WAVES_CYCLE);
        float wETime = mod(floor(iTime / WAVES_CYCLE), 1.) - dTime - (nCycle * WAVES_CYCLE);// * TIME_SPEED_FACTOR * 1.; // wave epicentrum time - where the wave was initiated
        float wCTime = mod(iTime, WAVES_CYCLE) - dTime;// * TIME_SPEED_FACTOR * 1.;// + deltaTime / 800.; // wave current time - where the wave is currently 
        vec3 sc = wanderOnSphere(wETime, BALL_RADIUS, nCycle); 
        sc = applyOppositeMovement(sc);
        float dd = pow(length(sc - pii), -1.);

        switch (distanceMethod) {
            case 1: dd = pow(length(sc - pii), 3.); break;
            case 2: dd = length(sc - pii * 1.);
            case 3: dd = abs(sc.x - pii.x) + abs(sc.y - pii.y) + abs(sc.z - pii.z); break;
            case 4: dd = geodesicDistanceWithDeviation(sc, pii, vec3(1.0, 100.0, 0.01), 0.9); break;
            case 5: dd = geodesicDistanceWithDeviation(sc, pii, vec3(0.02, 0.01, 0.01), 0.9); break;
            case 6: dd = length(sc - pii) != 0. ? 3. / length(sc - pii) : 0.; break; // harmonic distance
            case 7: dd = geodesicDistanceWithDeviation(sc, pii, vec3(6.0, 100.0, 0.01), 0.6); break; // harmonic distance

        }

        float dt = max(0., (DAMPING_TIME - wCTime)) / DAMPING_TIME;
        float d1 = wCTime; float d2 = d1 + mix(WAVE_SIZE, 0., 1. -dt);


        if (dd > d1 && dd < d2) {
            vec3 targetColor = mix(color, spotLight1, clamp((DAMPING_TIME - wCTime) / DAMPING_TIME, 0., 1.));
            targetColor *= color;
            float dc = (d1 + d2) / 2.;
            color = mix(targetColor, color, smoothstep(dc, (dd <= dc ? d1 :d2), dd));
        }
    }



    color = clamp(color, 0., 1.);


    vec2 q = fragCoord.xy / iResolution.xy;
    color = vec3(color * pow(20. * q.x * q.y * (1.0 - q.x) * (1.0 - q.y), 0.5)); // vigniete

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    grey = greyM();

    vec3 lookAt = vec3(0.0,0.5, 0.);// iTime * TIME_SPEED_FACTOR);
    vec3 ro = calculateCameraPosition(lookAt, uv);
    vec3 rd = camera(ro, lookAt) * normalize(vec3(uv, -1.2)); 
    vec3 lo = calculateLightPosition(lookAt);

//    vec4 backgroundColor = vec4(mix(vec3(0., 0.01, .1), vec3(0., 0., 0.), uv.y) * 1.8, 1.0);
    vec4 backgroundColor = vec4(0., 0., 0., 1.0);
    RaymarchRes rr = raymarch(ro, rd);

    fragColor = (rr.d < MAX_DISTANCE) ? vec4(calculateLight(fragCoord, rr, rd, lo, backgroundColor.xyz), 1.0) : backgroundColor;    
}

mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}

mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}

mat3 rotateReverseY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, -s),
        vec3(0, 1, 0),
        vec3(s, 0, c)
    );
}


mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
